const List<Map<String, dynamic>> _versiculosLocal = [
  { "id": 1, "ref": "1 Pedro 4:10", "texto": "Cada um coloque ao serviço dos outros o dom que recebeu, como bons administradores da multiforme graça de Deus." },
  { "id": 2, "ref": "Colossenses 3:23", "texto": "Tudo o que fizerem, façam de todo o coração, como para o Senhor, e não para os homens." },
  { "id": 3, "ref": "Romanos 12:6", "texto": "Temos dons diferentes, segundo a graça que nos foi dada. Se o dom de alguém é profecia, que o exerça de acordo com a sua fé." },
  { "id": 4, "ref": "1 Coríntios 12:4-5", "texto": "Há diferentes dons, mas o mesmo Espírito. Há diferentes ministérios, mas o mesmo Senhor." },
  { "id": 5, "ref": "2 Timóteo 1:6", "texto": "Por essa razão, lembro você de que deve avivar o dom de Deus que há em você por meio da imposição das minhas mãos." },
  { "id": 6, "ref": "Efésios 4:11-12", "texto": "Foi ele quem constituiu uns apóstolos, outros profetas, outros evangelistas, e outros pastores e mestres, para preparar os santos para a obra do ministério, a fim de edificar o corpo de Cristo." },
  { "id": 7, "ref": "1 Coríntios 15:58", "texto": "Portanto, meus amados irmãos, sede firmes e inabaláveis. Sempre abundai na obra do Senhor, pois sabeis que o trabalho de vocês no Senhor não é em vão." },
  { "id": 8, "ref": "Marcos 10:43-44", "texto": "Quem quiser tornar-se importante entre vocês deverá ser servo de vocês, e quem quiser ser o primeiro deverá ser escravo de todos." },
  { "id": 9, "ref": "Josué 1:9", "texto": "Não fui eu que ordenei a você? Seja forte e corajoso! Não se apavore nem desanime, pois o Senhor, o seu Deus, estará com você por onde você andar." },
  { "id": 10, "ref": "Isaías 6:8", "texto": "Então ouvi a voz do Senhor dizendo: A quem enviarei? Quem há de ir por nós? Respondi: Aqui estou! Envia-me a mim!" },
  { "id": 11, "ref": "Mateus 5:14", "texto": "Vocês são a luz do mundo. Não se pode esconder uma cidade construída sobre um monte." },
  { "id": 12, "ref": "2 Coríntios 4:1", "texto": "Por isso, tendo este ministério, por causa da misericórdia que nos foi concedida, não desanimamos." },
  { "id": 13, "ref": "Filipenses 4:13", "texto": "Tudo posso naquele que me fortalece." },
  { "id": 14, "ref": "1 Tessalonicenses 5:12", "texto": "Pedimos que reconheçam os que trabalham arduamente entre vocês, que os guiam no Senhor e os advertem." },
  { "id": 15, "ref": "Neemias 8:10", "texto": "A alegria do Senhor é a nossa força." },
  { "id": 16, "ref": "Romanos 12:11", "texto": "Não sejam negligentes no zelo; sejam fervorosos no espírito; sirvam ao Senhor." },
  { "id": 17, "ref": "1 Coríntios 4:2", "texto": "Ora, o que se requer dos administradores é que cada um seja encontrado fiel." },
  { "id": 18, "ref": "Gálatas 6:9", "texto": "Não nos cansemos de fazer o bem, pois, se não desanimarmos, a seu tempo colheremos." },
  { "id": 19, "ref": "Hebreus 13:20-21", "texto": "Que o Deus da paz vos complete em todo o bem para que façais a sua vontade, fazendo em nós o que é agradável à sua vista, por Jesus Cristo, ao qual seja a glória pelos séculos dos séculos." },
  { "id": 20, "ref": "Mateus 28:19", "texto": "Portanto, ide e fazei discípulos de todas as nações, batizando-os em nome do Pai e do Filho e do Espírito Santo." },
  { "id": 21, "ref": "1 Crônicas 28:20", "texto": "Seja forte e corajoso, e faça o trabalho. Não tenha medo nem desanime, pois Deus, o Senhor, meu Deus, estará com você. Não o deixará nem o abandonará." },
  { "id": 22, "ref": "Tito 1:7", "texto": "Pois o supervisor, como administrador de Deus, deve ser irrepreensível: não arrogante, não irascível, não dado ao vinho, não violento, não ganancioso." },
  { "id": 23, "ref": "2 Coríntios 9:8", "texto": "Deus pode fazer com que toda graça transborde para vocês, de modo que, em tudo e sempre, tendo tudo o que precisam, vocês transbordem em toda boa obra." },
  { "id": 24, "ref": "Isaías 40:31", "texto": "Mas os que esperam no Senhor renovam as suas forças. Voam alto como águias; correm e não ficam exaustos, caminham e não se cansam." },
  { "id": 25, "ref": "1 Timóteo 4:14", "texto": "Não negligencie o dom que você tem, o qual lhe foi dado mediante profecia, com a imposição de mãos pelo presbitério." },
  { "id": 26, "ref": "Romanos 12:7-8", "texto": "Se é servir, sirva; se é ensinar, ensine; se é encorajar, encoraje; se é contribuir, contribua generosamente; se é liderar, lidere com diligência; se é mostrar misericórdia, faça-o com alegria." },
  { "id": 27, "ref": "João 15:16", "texto": "Não foram vocês que me escolheram, mas eu os escolhi e os designei para que vão e deem fruto, fruto que permaneça." },
  { "id": 28, "ref": "2 Timóteo 2:15", "texto": "Procure apresentar-se a Deus aprovado, como obreiro que não tem do que se envergonhar e que maneja corretamente a palavra da verdade." },
  { "id": 29, "ref": "Provérbios 11:30", "texto": "O fruto do justo é árvore de vida, e o sábio conquista corações." },
  { "id": 30, "ref": "Miquéias 6:8", "texto": "Ele te declarou, ó homem, o que é bom e o que o Senhor requer de ti: que pratiques a justiça, e ames a misericórdia, e andes humildemente com o teu Deus." },
  { "id": 31, "ref": "1 Coríntios 12:27", "texto": "Ora, vocês são o corpo de Cristo, e cada um de vocês é membro desse corpo." },
  { "id": 32, "ref": "Efésios 6:7", "texto": "Sirva de boa vontade, como se estivesse servindo ao Senhor, e não aos homens." },
  { "id": 33, "ref": "Salmos 37:23", "texto": "O Senhor dirige os passos do homem íntegro e se agrada do seu caminho." },
  { "id": 34, "ref": "Jeremias 1:5", "texto": "Antes de eu te formar no ventre materno, eu te conheci; antes de você nascer, eu o separei; eu o constituí profeta para as nações." },
  { "id": 35, "ref": "Apocalipse 2:10", "texto": "Seja fiel até a morte, e eu lhe darei a coroa da vida." },
  { "id": 36, "ref": "2 Timóteo 4:2", "texto": "Pregue a palavra, esteja preparado a tempo e fora de tempo, repreenda, corrija e encoraje, com toda a paciência e doutrina." },
  { "id": 37, "ref": "Atos 20:24", "texto": "Contudo, não considero minha vida como algo precioso para mim mesmo, desde que possa terminar minha carreira e completar o ministério que recebi do Senhor Jesus." },
  { "id": 38, "ref": "Salmos 78:72", "texto": "E Davi os apascentou com integridade de coração e os guiou com destreza de mãos." },
  { "id": 39, "ref": "Provérbios 16:3", "texto": "Consagre ao Senhor tudo o que você faz, e os seus planos serão bem-sucedidos." },
  { "id": 40, "ref": "1 Coríntios 12:7", "texto": "A cada um é dada a manifestação do Espírito para o bem comum." },
  { "id": 41, "ref": "Mateus 25:21", "texto": "O seu senhor disse: Muito bem, servo bom e fiel! Você foi fiel com o pouco; vou pô-lo em charge de muito. Venha participar da alegria do seu senhor!" },
  { "id": 42, "ref": "Lucas 12:48", "texto": "De quem muito recebeu, muito será exigido; e de quem muito foi confiado, muito mais será pedido." },
  { "id": 43, "ref": "1 Pedro 5:2-3", "texto": "Apascente o rebanho de Deus que está aos seus cuidados, exercendo a supervisão, não por obrigação, mas de boa vontade, como Deus quer; não por amor ao dinheiro, mas com prontidão; não como dominadores dos que estão a seus cuidados, mas como exemplos para o rebanho." },
  { "id": 44, "ref": "Isaías 58:11", "texto": "O Senhor sempre o guiará; você será saciado nas terras áridas, e ele lhe dará força aos ossos. Você será como jardim irrigado, como fonte que nunca seca." },
  { "id": 45, "ref": "Filipenses 2:13", "texto": "Pois é Deus que realiza em vocês tanto o querer quanto o agir, de acordo com o seu bom propósito." },
  { "id": 46, "ref": "Atos 1:8", "texto": "Mas receberão poder quando o Espírito Santo descer sobre vocês, e serão minhas testemunhas em Jerusalém, em toda a Judeia e Samaria, e até os confins da terra." },
  { "id": 47, "ref": "Hebreus 12:1", "texto": "Portanto, também nós, visto que estamos rodeados de tão grande nuvem de testemunhas, lancemos fora todo o peso e o pecado que tão facilmente nos envolve, e corramos com perseverança a corrida que nos está proposta." },
  { "id": 48, "ref": "Salmos 27:14", "texto": "Espere pelo Senhor; seja forte e corajoso. Espere pelo Senhor!" },
  { "id": 49, "ref": "Romanos 11:29", "texto": "Porque os dons e o chamado de Deus são irrevogáveis." },
  { "id": 50, "ref": "2 Coríntios 3:5-6", "texto": "Não que sejamos capazes de pensar alguma coisa como saída de nós mesmos, mas a nossa capacidade vem de Deus, o qual nos capacitou para sermos ministros de uma nova aliança." },
  { "id": 51, "ref": "Salmos 92:14", "texto": "Ainda darão frutos na velhice; serão sempre viçosos e vigorosos." },
  { "id": 52, "ref": "Provérbios 3:5-6", "texto": "Confie no Senhor de todo o seu coração e não se apoie em seu próprio entendimento. Lembre-se do Senhor em tudo o que fizer, e ele aplanará os seus caminhos." },
  { "id": 53, "ref": "João 21:17", "texto": "Jesus disse: Apascenta as minhas ovelhas." },
  { "id": 54, "ref": "1 Coríntios 9:16", "texto": "Pois se eu prego o evangelho, não tenho do que me orgulhar, pois estou cumprindo um dever. Ai de mim se eu não pregar o evangelho!" },
  { "id": 55, "ref": "Ezequiel 3:17", "texto": "Filho do homem, eu te faço sentinela para a casa de Israel; ouve o que eu disser e dá-lhes o meu aviso." },
  { "id": 56, "ref": "Efésios 2:10", "texto": "Pois somos criação de Deus realizada em Cristo Jesus para fazermos boas obras, as quais Deus preparou de antemão para que as praticássemos." },
  { "id": 57, "ref": "2 Timóteo 2:2", "texto": "E as coisas que ouviu de mim na presença de muitas testemunhas, confie-as a pessoas confiáveis e aptas para ensinar os outros." },
  { "id": 58, "ref": "Números 11:17", "texto": "Eu descerei e falarei com você ali; tomarei do Espírito que está sobre você e porei sobre eles, para que levem com você o encargo do povo." },
  { "id": 59, "ref": "Filipenses 1:6", "texto": "Tendo plena confiança de que aquele que começou boa obra em vocês a completará até o dia de Cristo Jesus." },
  { "id": 60, "ref": "Salmos 34:8", "texto": "Prove e veja que o Senhor é bom; feliz é o homem que nele se refugia." },
  { "id": 61, "ref": "1 Timóteo 3:1", "texto": "Esta é uma declaração digna de confiança: se alguém deseja a função de supervisor, deseja uma boa obra." },
  { "id": 62, "ref": "Deuteronômio 31:8", "texto": "O próprio Senhor vai adiante de você e estará com você; não o deixará nem o abandonará. Não tema nem se desanime." },
  { "id": 63, "ref": "Romanos 8:28", "texto": "Sabemos que Deus age em todas as coisas para o bem daqueles que o amam, dos que foram chamados de acordo com o seu propósito." },
  { "id": 64, "ref": "1 Tessalonicenses 2:4", "texto": "Pelo contrário, falamos como homens aprovados por Deus para nos confiar o evangelho; não procuramos agradar aos homens, mas a Deus, que examina nossos corações." },
  { "id": 65, "ref": "Lucas 22:26", "texto": "Mas o maior entre vocês deve se comportar como o menor, e o que governa como o que serve." },
  { "id": 66, "ref": "Isaías 52:7", "texto": "Que belos são os pés dos que trazem boas novas, dos que proclamam a paz, dos que anunciam coisas boas!" },
  { "id": 67, "ref": "1 Coríntios 3:9", "texto": "Pois somos colaboradores de Deus; vocês são lavoura de Deus, edifício de Deus." },
  { "id": 68, "ref": "Salmos 23:3", "texto": "Guia-me nas veredas da justiça por amor do seu nome." },
  { "id": 69, "ref": "João 13:14", "texto": "Pois, se eu, sendo o Senhor e o Mestre, lavei os pés de vocês, também vocês devem lavar os pés uns dos outros." },
  { "id": 70, "ref": "Hebreus 13:17", "texto": "Obedeçam aos seus líderes e submetam-se à autoridade deles, pois eles cuidam de vocês como quem tem que prestar contas." },
  { "id": 71, "ref": "Provérbios 27:23", "texto": "Cuide bem dos seus rebanhos; preste attention aos seus manadas." },
  { "id": 72, "ref": "1 Coríntios 1:27", "texto": "Mas Deus escolheu as coisas loucas do mundo para envergonhar os sábios, e escolheu as coisas fracas do mundo para envergonhar as fortes." },
  { "id": 73, "ref": "2 Coríntios 6:3-4", "texto": "Não colocamos obstáculo no caminho de ninguém, para que o nosso ministério não seja desacreditado. Pelo contrário, em tudo nos recomendamos como ministros de Deus." },
  { "id": 74, "ref": "Salmos 119:105", "texto": "A tua palavra é lâmpada para os meus pés e luz para o meu caminho." },
  { "id": 75, "ref": "Ezequiel 34:2", "texto": "Ai dos pastores de Israel que só cuidam de si mesmos! Os pastores não devem cuidar do rebanho?" },
  { "id": 76, "ref": "Tiago 1:5", "texto": "Se algum de vocês tem falta de sabedoria, peça-a a Deus, que a todos dá livremente, sem fazer censura, e lhe será concedida." },
  { "id": 77, "ref": "João 10:11", "texto": "Eu sou o bom pastor. O bom pastor dá a sua vida pelas ovelhas." },
  { "id": 78, "ref": "Atos 6:3-4", "texto": "Irmãos, escolham dentre vocês sete homens reconhecidamente cheios do Espírito e de sabedoria, para que os encarreguemos desta tarefa. E nós nos dedicaremos à oração e ao ministério da palavra." },
  { "id": 79, "ref": "1 Pedro 4:11", "texto": "Se alguém fala, fale como quem diz palavras de Deus; se alguém serve, sirva com a força que Deus dá, para que em tudo Deus seja glorificado por meio de Jesus Cristo." },
  { "id": 80, "ref": "Filipenses 2:3-4", "texto": "Nada façam por ambição egoísta ou por vaidade, mas humildemente considerem os outros superiores a vocês mesmos. Cada um cuide, não somente dos seus próprios interesses, mas também dos interesses dos outros." },
  { "id": 81, "ref": "Romanos 12:1", "texto": "Portanto, irmãos, apelo a vocês, pela misericórdia de Deus, que se ofereçam em sacrifício vivo, santo e agradável a Deus; este é o culto racional de vocês." },
  { "id": 82, "ref": "2 Crônicas 15:7", "texto": "Mas quanto a vocês, sejam fortes e não se desanimem, pois o seu trabalho terá recompensa." },
  { "id": 83, "ref": "Salmos 75:6-7", "texto": "Pois a promoção não vem do oriente, nem do ocidente, nem do sul. Mas Deus é o juiz: a um humilha, e a outro exalta." },
  { "id": 84, "ref": "Mateus 9:37-38", "texto": "A colheita é grande, mas os trabalhadores são poucos. Peçam, portanto, ao Senhor da colheita que mande trabalhadores para a sua colheita." },
  { "id": 85, "ref": "Atos 2:42", "texto": "Perseveravam no ensino dos apóstolos, na comunhão fraterna, no partir do pão e nas orações." },
  { "id": 86, "ref": "1 Coríntios 12:12", "texto": "Assim como o corpo é um e tem muitos membros, e todos os membros, embora muitos, formam um corpo, assim também é Cristo." },
  { "id": 87, "ref": "Hebreus 6:10", "texto": "Deus não é injusto para esquecer o trabalho de vocês e o amor que demonstraram pelo seu nome quando serviram e continuam servindo aos santos." },
  { "id": 88, "ref": "Provérbios 31:26", "texto": "Fala com sabedoria, e ensinamentos bondosos estão em sua língua." },
  { "id": 89, "ref": "Salmos 20:4", "texto": "Conceda-lhe o desejo do seu coração e realize todos os seus planos." },
  { "id": 90, "ref": "Isaías 41:10", "texto": "Não tema, porque eu sou com você; não se atemorize, porque eu sou o seu Deus. Eu o fortaleço e o ajudo; eu o sustento com a minha direta vitoriosa." },
  { "id": 91, "ref": "2 Coríntios 12:9", "texto": "Mas ele me disse: A minha graça é suficiente para você, pois o meu poder se aperfeiçoa na fraqueza. Portanto, eu me gloriarei muito mais de minhas fraquezas, para que o poder de Cristo repouse sobre mim." },
  { "id": 92, "ref": "Tiago 5:16", "texto": "A oração fervorosa do justo tem grande eficácia." },
  { "id": 93, "ref": "Romanos 1:16", "texto": "Pois não me envergonho do evangelho, porque é o poder de Deus para a salvação de todo aquele que crê." },
  { "id": 94, "ref": "Atos 4:31", "texto": "Depois de orarem, o lugar onde estavam reunidos tremeu, e todos ficaram cheios do Espírito Santo e proclamavam a palavra de Deus com ousadia." },
  { "id": 95, "ref": "1 Timóteo 4:16", "texto": "Cuide de si mesmo e da sua doutrina; persevere nessas coisas, pois assim você se salvará e salvará aqueles que o ouvirem." },
  { "id": 96, "ref": "Mateus 5:13", "texto": "Vocês são o sal da terra. Mas se o sal perder o sabor, como será salgado novamente? Para nada mais presta, a não ser para ser jogado fora e pisado pelos homens." },
  { "id": 97, "ref": "Salmos 46:1", "texto": "Deus é o nosso refúgio e a nossa força, socorro bem presente nas tribulações." },
  { "id": 98, "ref": "Jeremias 29:11", "texto": "Porque sei os planos que tenho para vocês, diz o Senhor, planos de fazer-lhes bem e não de causar-lhes mal, planos de dar-lhes um futuro e uma esperança." },
  { "id": 99, "ref": "Salmos 126:5-6", "texto": "Os que semeiam com lágrimas colherão com cantos de alegria. Aquele que sai chorando enquanto lança a semente voltará com alegria, trazendo os seus feixes." },
  { "id": 100, "ref": "Efésios 3:20", "texto": "Ora, àquele que pode fazer infinitamente mais do que tudo o que pedimos ou pensamos, de acordo com o seu poder que opera em nós." },
  { "id": 101, "ref": "Salmos 37:4", "texto": "Deleite-se no Senhor, e ele atenderá aos pedidos do seu coração." },
  { "id": 102, "ref": "Habacuque 2:2", "texto": "Então o Senhor me respondeu: Escreve a visão e grava-a em tábuas, para que possa ser lida de relance." },
  { "id": 103, "ref": "1 Coríntios 2:1-2", "texto": "Quando fui a vocês, irmãos, não fui com eloquência ou grande sabedoria ao proclamar-lhes o testemunho de Deus. Pois resolvi nada saber entre vocês, a não ser Jesus Cristo, e este crucificado." },
  { "id": 104, "ref": "Êxodo 18:21", "texto": "Além disso, escolha dentre o povo homens capazes, tementes a Deus, fiéis e que odeiem ganância desonesta, e os nomeie como chefes." },
  { "id": 105, "ref": "Lucas 16:10", "texto": "Quem é fiel nas coisas pequenas, também é fiel nas grandes; e quem é desonesto nas coisas pequenas, também é desonesto nas grandes." },
  { "id": 106, "ref": "Salmos 71:17-18", "texto": "Ó Deus, me ensinaste desde a minha mocidade, e até agora proclamo as tuas maravilhas. Mesmo na velhice e nas cãs, ó Deus, não me abandones." },
  { "id": 107, "ref": "2 Timóteo 4:7", "texto": "Combati o bom combate, completei a corrida, guardei a fé." },
  { "id": 108, "ref": "Mateus 20:28", "texto": "Assim como o Filho do Homem não veio para ser servido, mas para servir e dar a sua vida em resgate por muitos." },
  { "id": 109, "ref": "1 Coríntios 16:13-14", "texto": "Vigiem, estejam firmes na fé, tenham coragem, sejam fortes. Façam tudo com amor." },
  { "id": 110, "ref": "Atos 20:28", "texto": "Tenham cuidado de si mesmos e de todo o rebanho sobre o qual o Espírito Santo os constituiu bispos, para pastorearem a igreja de Deus, que ele adquiriu com o próprio sangue." },
  { "id": 111, "ref": "Salmos 119:11", "texto": "Guardei a tua palavra no meu coração para não pecar contra ti." },
  { "id": 112, "ref": "Provérbios 22:29", "texto": "Você vê alguém hábil no seu trabalho? Esse estará diante de reis e não diante de obscuros." },
  { "id": 113, "ref": "João 17:17", "texto": "Santifica-os pela verdade; a tua palavra é a verdade." },
  { "id": 114, "ref": "Filipenses 3:14", "texto": "Prossigo em direção à meta, para ganhar o prêmio do chamado celestial de Deus em Cristo Jesus." },
  { "id": 115, "ref": "Isaías 61:1", "texto": "O Espírito do Senhor está sobre mim, porque o Senhor me ungiu para pregar boas novas aos pobres. Enviou-me para curar os quebrantados de coração, proclamar liberdade aos cativos." },
  { "id": 116, "ref": "Atos 13:2", "texto": "Enquanto adoravam ao Senhor e jejuavam, o Espírito Santo disse: Separem-me Barnabé e Saulo para a obra a qual os chamei." },
  { "id": 117, "ref": "2 Coríntios 5:20", "texto": "Somos embaixadores de Cristo, e é como se Deus fizesse o seu apelo por nosso intermédio." },
  { "id": 118, "ref": "Salmos 68:19", "texto": "Bendito seja o Senhor, que dia a dia leva os nossos fardos, o Deus que é a nossa salvação." },
  { "id": 119, "ref": "Romanos 10:15", "texto": "Como também, como pregará, se não for enviado? Como está escrito: Que formosos são os pés dos que pregam o evangelho das coisas boas!" },
  { "id": 120, "ref": "Hebreus 4:16", "texto": "Aproximemo-nos, portanto, com confiança do trono da graça, a fim de recebermos misericórdia e encontrarmos graça que nos ajude no momento em que mais precisarmos." },
  { "id": 121, "ref": "1 Coríntios 13:2", "texto": "Se eu tiver o dom de profecia e conhecer todos os mistérios e toda a ciência, e se eu tiver toda a fé, de modo a mover montanhas, mas não tiver amor, nada serei." },
  { "id": 122, "ref": "Salmos 1:2-3", "texto": "Pelo contrário, o seu prazer está na lei do Senhor, e nessa lei medita de dia e de noite. Será como árvore plantada junto a correntes de águas, que dá fruto no seu tempo." },
  { "id": 123, "ref": "2 Timóteo 3:16-17", "texto": "Toda a Escritura é inspirada por Deus e útil para o ensino, para a repreensão, para a correção e para a instrução na justiça, para que o homem de Deus seja apto e plenamente preparado para toda boa obra." },
  { "id": 124, "ref": "Mateus 5:16", "texto": "Assim brilhe a luz de vocês diante dos homens, para que vejam as suas boas obras e glorifiquem o Pai de vocês que está nos céus." },
  { "id": 125, "ref": "Colossenses 1:28", "texto": "Nós o proclamamos, aconselhando e ensinando a todos com toda a sabedoria, para que apresentemos a todos perfeitos em Cristo." },
  { "id": 126, "ref": "1 Crônicas 16:11", "texto": "Busquem o Senhor e o seu poder; busquem sempre a sua face." },
  { "id": 127, "ref": "João 15:5", "texto": "Eu sou a videira; vocês são os ramos. Se alguém permanecer em mim e eu nele, esse dará muito fruto; sem mim, vocês não podem fazer coisa alguma." },
  { "id": 128, "ref": "Romanos 15:13", "texto": "Que o Deus da esperança os encha de toda alegria e paz, por sua confiança nele, para que vocês transbordem de esperança pelo poder do Espírito Santo." },
  { "id": 129, "ref": "Efésios 4:15", "texto": "Antes, falando a verdade em amor, cresçamos em tudo naquele que é a cabeça, Cristo." },
  { "id": 130, "ref": "Salmos 32:8", "texto": "Vou instruí-lo e ensiná-lo no caminho que você deve seguir; vou aconselhá-lo e sobre você terei minha vista." },
  { "id": 131, "ref": "1 Timóteo 2:1-2", "texto": "Exorto, pois, primeiramente, que se façam súplicas, orações, intercessões e ações de graças por todos os homens; pelos reis e por todos os que têm autoridade." },
  { "id": 132, "ref": "Isaías 50:4", "texto": "O Senhor me deu língua de erudito, para que eu saiba confortar com palavras o que está cansado. Cada manhã ele desperta, desperta o meu ouvido para ouvir como os que são ensinados." },
  { "id": 133, "ref": "Lucas 4:18", "texto": "O Espírito do Senhor está sobre mim, por isso ele me ungiu para proclamar boas novas aos pobres. Ele me enviou para proclamar liberdade aos presos e recuperação da vista aos cegos." },
  { "id": 134, "ref": "2 Coríntios 4:5", "texto": "Pois não pregamos a nós mesmos, mas a Cristo Jesus como Senhor, e a nós mesmos como servos de vocês por amor a Jesus." },
  { "id": 135, "ref": "Salmos 40:8", "texto": "Tenho prazer em fazer a tua vontade, ó meu Deus; e a tua lei está dentro do meu coração." },
  { "id": 136, "ref": "Romanos 12:16", "texto": "Vivam em harmonia uns com os outros. Não sejam arrogantes, mas associem-se com os humildes. Não se julguem sábios." },
  { "id": 137, "ref": "João 12:26", "texto": "Quem quiser me servir, deve me seguir; e onde eu estiver, ali também estará o meu servo. Se alguém me servir, o Pai o honrará." },
  { "id": 138, "ref": "Hebreus 11:6", "texto": "Sem fé é impossível agradar a Deus, pois quem dele se aproxima precisa crer que ele existe e que recompensa aqueles que o buscam." },
  { "id": 139, "ref": "Mateus 25:35-36", "texto": "Pois tive fome, e vocês me deram de comer; tive sede, e vocês me deram de beber; fui estrangeiro, e vocês me hospedaram; precisei de roupas, e vocês me vestiram; fiquei doente, e vocês cuidaram de mim." },
  { "id": 140, "ref": "Salmos 100:2", "texto": "Sirva ao Senhor com alegria; venha diante dele com cânticos de júbilo." },
  { "id": 141, "ref": "1 Coríntios 3:6-7", "texto": "Eu plantei, Apolo regou, mas foi Deus quem fez crescer. Portanto, nem o que planta nem o que rega é alguma coisa, mas apenas Deus que faz crescer." },
  { "id": 142, "ref": "2 Coríntios 1:3-4", "texto": "Bendito seja o Deus e Pai de nosso Senhor Jesus Cristo, o Pai misericordioso e Deus de todo o consolo, que nos consola em todas as nossas tribulações, para que possamos consolar os que estão em qualquer tribulação." },
  { "id": 143, "ref": "Gálatas 5:13", "texto": "Vocês foram chamados para a liberdade, irmãos; não usem a liberdade para dar oportunidade à carne, mas sirvam uns aos outros pelo amor." },
  { "id": 144, "ref": "Provérbios 13:17", "texto": "Um mensageiro perverso cai em desgraça, mas um enviado fiel traz saúde." },
  { "id": 145, "ref": "Jeremias 3:15", "texto": "E vos darei pastores segundo o meu coração, que vos apascentem com ciência e com inteligência." },
  { "id": 146, "ref": "Atos 5:42", "texto": "E todos os dias, tanto no templo como de casa em casa, não cessavam de ensinar e de anunciar o evangelho de Jesus Cristo." },
  { "id": 147, "ref": "Romanos 15:1", "texto": "Nós, os fortes, temos a obrigação de suportar as fraquezas dos que não são fortes, e não devemos agradar a nós mesmos." },
  { "id": 148, "ref": "Filipenses 2:16", "texto": "Sustentando a palavra da vida, para que eu me possa gloriar, no dia de Cristo, de que não corri nem trabalhei em vão." },
  { "id": 149, "ref": "Salmos 63:1", "texto": "Ó Deus, tu és o meu Deus! Eu te busco com ardor. A minha alma tem sede de ti; o meu corpo anseia por ti." },
  { "id": 150, "ref": "Efésios 5:15-16", "texto": "Portanto, tenham muito cuidado com o modo como vivem, não como insensatos, mas como sábios, aproveitando ao máximo cada oportunidade, porque os dias são maus." },
  { "id": 151, "ref": "1 Pedro 3:15", "texto": "Mas santifiquem Cristo como Senhor em seus corações. Estejam sempre preparados para responder a qualquer pessoa que pedir a vocês uma razão da esperança que vocês têm." },
  { "id": 152, "ref": "Mateus 24:45", "texto": "Quem é o servo fiel e prudente, a quem o seu senhor confiou os seus servos para dar-lhes o alimento no tempo certo?" },
  { "id": 153, "ref": "Isaías 43:10", "texto": "Vocês são minhas testemunhas, diz o Senhor, e meu servo que escolhi, para que vocês me conheçam e creiam em mim e entendam que eu sou ele." },
  { "id": 154, "ref": "Colossenses 4:17", "texto": "Digam a Arquipo: Preste atenção ao ministério que você recebeu no Senhor, para que o cumpra." },
  { "id": 155, "ref": "1 Tessalonicenses 5:24", "texto": "Aquele que os chama é fiel, e ele o fará." },
  { "id": 156, "ref": "2 Pedro 1:10", "texto": "Portanto, irmãos, esforcem-se cada vez mais para confirmar sua vocação e eleição, pois, procedendo assim, vocês jamais tropeçarão." },
  { "id": 157, "ref": "Salmos 91:15", "texto": "Ele me invocará, e eu lhe responderei; estarei com ele na angústia; dele a tirarei e o glorificarei." },
  { "id": 158, "ref": "Marcos 16:15", "texto": "Disse-lhes: Ide por todo o mundo e pregai o evangelho a toda criatura." },
  { "id": 159, "ref": "João 20:21", "texto": "Novamente Jesus disse: Paz seja com vocês! Assim como o Pai me enviou, eu também os envio." },
  { "id": 160, "ref": "Romanos 12:13", "texto": "Partilhe com os santos que passam necessidades; pratique a hospitalidade." },
  { "id": 161, "ref": "Tiago 1:22", "texto": "Não se limitem a ouvir a palavra e, assim, iludir a si mesmos. Façam o que ela diz." },
  { "id": 162, "ref": "1 Coríntios 9:22", "texto": "Para os fracos tornei-me fraco, para ganhar os fracos. Tornei-me tudo para todos, para que por todos os meios salvasse alguns." },
  { "id": 163, "ref": "Ezequiel 22:30", "texto": "Busquei entre eles alguém que reparasse a brecha e que ficasse diante de mim em favor da terra, para que eu não a destruísse; mas não achei ninguém." },
  { "id": 164, "ref": "Provérbios 4:23", "texto": "Acima de tudo, guarde o seu coração, pois dele depende toda a sua vida." },
  { "id": 165, "ref": "Salmos 122:1", "texto": "Alegrei-me quando me disseram: Vamos à casa do Senhor!" },
  { "id": 166, "ref": "2 Crônicas 7:14", "texto": "Se o meu povo, que se chama pelo meu nome, se humilhar e orar e buscar a minha face e se converter dos seus maus caminhos, então eu ouvirei dos céus, perdoarei os seus pecados e sararei a sua terra." },
  { "id": 167, "ref": "Marcos 12:30", "texto": "Ame o Senhor, o seu Deus, de todo o seu coração, de toda a sua alma, de todo o seu entendimento e de todas as suas forças." },
  { "id": 168, "ref": "Hebreus 10:24-25", "texto": "Pensemos também em como nos estimular mutuamente ao amor e às boas obras. Não deixemos de nos reunir, como alguns têm por costume, mas encorajemo-nos uns aos outros." },
  { "id": 169, "ref": "Mateus 18:20", "texto": "Pois onde dois ou três se reúnem em meu nome, ali estou eu no meio deles." },
  { "id": 170, "ref": "Efésios 1:18", "texto": "Peço também que os olhos do coração de vocês sejam iluminados, para que saibam qual é a esperança do chamado de Deus." },
  { "id": 171, "ref": "1 Coríntios 14:12", "texto": "Assim também vocês, já que anseiam pelos dons espirituais, esforcem-se em abundar para a edificação da igreja." },
  { "id": 172, "ref": "Jeremias 20:9", "texto": "Mas se eu digo: Não me lembrarei mais dele e não falarei mais em seu nome, então isso é como fogo ardendo no meu coração, encerrado nos meus ossos." },
  { "id": 173, "ref": "Salmos 138:8", "texto": "O Senhor cumprirá o seu propósito em mim; a tua misericórdia, Senhor, dura para sempre; não abandones as obras das tuas mãos." },
  { "id": 174, "ref": "Romanos 8:14", "texto": "Pois todos os que são guiados pelo Espírito de Deus são filhos de Deus." },
  { "id": 175, "ref": "Lucas 10:2", "texto": "Disse-lhes: A colheita é grande, mas os trabalhadores são poucos. Portanto, peçam ao Senhor da colheita que mande trabalhadores para a sua colheita." },
  { "id": 176, "ref": "2 Timóteo 1:7", "texto": "Porque Deus não nos deu espírito de covardia, mas de poder, de amor e de equilíbrio." },
  { "id": 177, "ref": "João 4:35", "texto": "Não dizem vocês que ainda faltam quatro meses para a colheita? Pois bem, eu digo: Abram os olhos e vejam os campos! Eles estão maduros para a colheita." },
  { "id": 178, "ref": "Salmos 84:10", "texto": "Pois um dia nos teus átrios vale mais do que mil em outro lugar. Prefiro estar à porta da casa de meu Deus a residir nas tendas dos perversos." },
  { "id": 179, "ref": "Atos 14:22", "texto": "Fortaleciam os discípulos e os encorajavam a permanecer na fé, dizendo-lhes que é necessário passar por muitas tribulações para entrarmos no reino de Deus." },
  { "id": 180, "ref": "1 Pedro 2:9", "texto": "Mas vocês são raça eleita, sacerdócio real, nação santa, povo peculiar de Deus, a fim de que proclamem as virtudes daquele que os chamou das trevas para a sua luz maravilhosa." },
  { "id": 181, "ref": "Efésios 6:10", "texto": "Finalmente, fortaleçam-se no Senhor e no seu imenso poder." },
  { "id": 182, "ref": "Tito 2:7-8", "texto": "Em tudo isso, você mesmo deverá ser exemplo de boas obras. Em seu ensino, mostre integridade, seriedade e palavra sã, irreprovável, para que o adversário se envergonhe." },
  { "id": 183, "ref": "Salmos 28:7", "texto": "O Senhor é a minha força e o meu escudo; nele confia o meu coração, e sou socorrido. Meu coração exulta de alegria, e com o meu cântico o louvarei." },
  { "id": 184, "ref": "Romanos 12:15", "texto": "Alegrem-se com os que se alegram; chorem com os que choram." },
  { "id": 185, "ref": "Colossenses 3:16", "texto": "Deixem que a palavra de Cristo habite em vocês em toda a sua riqueza, ensinando e admoestando-se mutuamente com toda a sabedoria." },
  { "id": 186, "ref": "Salmos 103:1", "texto": "Bendize, ó minha alma, ao Senhor; e todo o meu ser, ao seu santo nome." },
  { "id": 187, "ref": "Lucas 9:62", "texto": "Jesus respondeu: Nenhum que coloca a mão no arado e olha para trás é apto para o reino de Deus." },
  { "id": 188, "ref": "1 Coríntios 12:18", "texto": "Mas Deus dispôs os membros no corpo, cada um deles como lhe aprouve." },
  { "id": 189, "ref": "Hebreus 13:7", "texto": "Lembrem-se dos seus líderes que lhes pregaram a palavra de Deus; considerem o resultado do seu modo de vida e imitem a fé deles." },
  { "id": 190, "ref": "Mateus 23:11", "texto": "O maior entre vocês será servo de vocês." },
  { "id": 191, "ref": "Atos 18:9-10", "texto": "Certa noite, o Senhor disse em visão a Paulo: Não tenha medo; continue a falar e não fique calado, pois eu estou com você." },
  { "id": 192, "ref": "Filipenses 4:11", "texto": "Aprendi a viver satisfeito em qualquer situação em que me encontre." },
  { "id": 193, "ref": "Isaías 62:6", "texto": "Sobre os teus muros, ó Jerusalém, pus guardas; não ficarão em silêncio nem de dia nem de noite. Vós que lembrais o Senhor, não repouseis." },
  { "id": 194, "ref": "1 Pedro 1:13", "texto": "Portanto, estejam prontos para agir e sejam sóbrios; coloquem sua esperança completamente na graça que lhes será dada quando Jesus Cristo for revelado." },
  { "id": 195, "ref": "Provérbios 20:6", "texto": "Muitos homens proclamam a sua bondade, mas quem pode encontrar um homem fiel?" },
  { "id": 196, "ref": "2 Coríntios 2:14", "texto": "Mas graças a Deus, que em Cristo sempre nos leva em triunfo e por meio de nós manifesta em todo lugar a fragrância do seu conhecimento." },
  { "id": 197, "ref": "Zacarias 4:6", "texto": "Esta é a palavra do Senhor a Zorobabel: Não será pela força nem pelo poder, mas pelo meu Espírito, diz o Senhor dos Exércitos." },
  { "id": 198, "ref": "Salmos 18:32", "texto": "É Deus quem me reveste de força e torna perfeito o meu caminho." },
  { "id": 199, "ref": "Mateus 10:8", "texto": "Curem os doentes, ressuscitem os mortos, purifiquem os que têm lepra, expulsem os demônios. Vocês receberam de graça; deem de graça." },
  { "id": 200, "ref": "1 João 4:19", "texto": "Nós amamos porque ele nos amou primeiro." },
  { "id": 201, "ref": "Romanos 12:10", "texto": "Amem-se uns aos outros com amor fraternal; prefiram honrar os outros e não a vocês mesmos." },
  { "id": 202, "ref": "Salmos 55:22", "texto": "Lança sobre o Senhor o teu fardo, e ele te sustentará; ele nunca permitirá que o justo seja abalado." },
  { "id": 203, "ref": "Colossenses 3:12", "texto": "Como eleitos de Deus, saints e amados, revistam-se de compaixão, bondade, humildade, mansidão e paciência." },
  { "id": 204, "ref": "2 Tessalonicenses 3:13", "texto": "Quanto a vocês, irmãos, não se cansem de fazer o bem." },
  { "id": 205, "ref": "Efésios 4:7", "texto": "Mas a cada um de nós foi concedida a graça de acordo com a medida do dom de Cristo." },
  { "id": 206, "ref": "Provérbios 28:20", "texto": "O homem fiel será muito abençoado, mas o que tem pressa em enriquecer não ficará sem punição." },
  { "id": 207, "ref": "Isaías 55:11", "texto": "Assim será a minha palavra que sai da minha boca: ela não voltará para mim vazia, mas realizará o que desejo e alcançará o propósito para o qual a enviei." },
  { "id": 208, "ref": "Salmos 31:23", "texto": "Amai ao Senhor, todos os seus santos; o Senhor preserva os fiéis e paga com abundância aos que agem com arrogância." },
  { "id": 209, "ref": "2 Coríntios 10:3-4", "texto": "Pois, embora vivamos no mundo, não guerreamos segundo os padrões do mundo. As armas com que guerreamos não são as do mundo." },
  { "id": 210, "ref": "Números 27:18", "texto": "Disse o Senhor a Moisés: Toma Josué, filho de Num, homem em quem está o Espírito, e impõe-lhe a mão." },
  { "id": 211, "ref": "Salmos 16:11", "texto": "Tu me mostrarás o caminho da vida; na tua presença há alegria plena e na tua destra há prazeres eternos." },
  { "id": 212, "ref": "1 Coríntios 14:26", "texto": "O que fazer, irmãos? Quando se reunirem, cada um de vocês tem um salmo, um ensino, uma revelação, uma fala em línguas ou uma interpretação. Tudo isso deve ser feito para a edificação da igreja." },
  { "id": 213, "ref": "Mateus 28:20", "texto": "Ensinando-os a guardar todas as coisas que vos ordenei; e eis que eu estou convosco todos os dias, até a consumação dos séculos." },
  { "id": 214, "ref": "Hebreus 10:36", "texto": "Vocês precisam de perseverança, para que, depois de terem feito a vontade de Deus, possam receber o que ele prometeu." },
  { "id": 215, "ref": "Tiago 3:17", "texto": "A sabedoria que vem do alto é, antes de tudo, pura; depois pacífica, amável, dócil, plena de misericórdia e de bons frutos, imparcial e sem hipocrisia." },
  { "id": 216, "ref": "Atos 16:5", "texto": "Assim as igrejas se fortaleciam na fé e cresciam em número a cada dia." },
  { "id": 217, "ref": "Salmos 25:4-5", "texto": "Ensina-me os teus caminhos, ó Senhor; instrui-me nas tuas veredas. Guia-me na tua verdade e ensina-me, pois tu és o Deus da minha salvação." },
  { "id": 218, "ref": "Romanos 10:17", "texto": "Consequentemente, a fé vem pela pregação da mensagem, e a mensagem é ouvida mediante a palavra de Cristo." },
  { "id": 219, "ref": "Filipenses 1:27", "texto": "Seja como for, vivam de maneira digna do evangelho de Cristo, para que, quer eu vá vê-los, quer fique longe, ouça que vocês permanecem firmes num só espírito." },
  { "id": 220, "ref": "2 Coríntios 5:14", "texto": "Pois o amor de Cristo nos domina, porque estamos convictos de que um morreu por todos e, por isso, todos morreram." },
  { "id": 221, "ref": "Lucas 14:27", "texto": "E quem não traz a sua cruz e não vem após mim não pode ser meu discípulo." },
  { "id": 222, "ref": "Salmos 51:12-13", "texto": "Restaura em mim a alegria da tua salvação e sustenta-me com espírito voluntário. Então ensinarei os transgressores os teus caminhos, e os pecadores se converterão a ti." },
  { "id": 223, "ref": "Efésios 4:29", "texto": "Não saia da boca de vocês nenhuma palavra prejudicial, mas apenas a que for boa para edificar os outros conforme a necessidade, e que traga graça aos que ouvem." },
  { "id": 224, "ref": "Isaías 49:2", "texto": "Tornou a minha boca como espada afiada; escondeu-me na sombra da sua mão; fez de mim uma flecha afiada e me ocultou na sua aljava." },
  { "id": 225, "ref": "João 17:18", "texto": "Como tu me enviaste ao mundo, também eu os enviei ao mundo." },
  { "id": 226, "ref": "1 Tessalonicenses 1:5", "texto": "Porque o nosso evangelho não chegou a vocês somente em palavras, mas também em poder, no Espírito Santo e em plena convicção." },
  { "id": 227, "ref": "Provérbios 15:22", "texto": "Os planos fracassam sem conselho, mas com muitos conselheiros, eles têm sucesso." },
  { "id": 228, "ref": "Salmos 119:33-34", "texto": "Ensina-me, Senhor, os teus decretos e eu os guardarei até o fim. Dá-me entendimento para guardar a tua lei e obedecê-la de todo o coração." },
  { "id": 229, "ref": "Romanos 8:37", "texto": "Em todas essas coisas somos mais que vencedores por meio daquele que nos amou." },
  { "id": 230, "ref": "Marcos 1:17", "texto": "Venham, sigam-me, disse Jesus, e eu os farei pescadores de homens." },
  { "id": 231, "ref": "2 Coríntios 11:28", "texto": "Além das coisas que não mencionei, tenho sobre mim a pressão de cada dia, o cuidado de todas as igrejas." },
  { "id": 232, "ref": "Tito 3:8", "texto": "Esta palavra é fiel, e quero que você insista nisso com firmeza, para que os que creram em Deus tenham cuidado em praticar boas obras." },
  { "id": 233, "ref": "Salmos 37:5", "texto": "Entrega o teu caminho ao Senhor; confia nele, e ele agirá." },
  { "id": 234, "ref": "Lucas 5:10", "texto": "Então Jesus disse a Simão: Não tenha medo; de agora em diante você pescará homens." },
  { "id": 235, "ref": "Atos 26:16", "texto": "Mas levanta-te e fica de pé, porque apareci a ti para te constituir ministro e testemunha tanto das coisas que viste como das que te mostrarei." },
  { "id": 236, "ref": "Efésios 4:16", "texto": "Da qual todo o corpo, bem ajustado e compacto pelo auxílio de cada junta, cresce e se edifica em amor à medida que cada parte faz o seu trabalho." },
  { "id": 237, "ref": "Salmos 33:11", "texto": "O plano do Senhor subsiste para sempre; os propósitos do seu coração, de geração em geração." },
  { "id": 238, "ref": "1 Coríntios 10:31", "texto": "Portanto, quer comam, quer bebam, quer façam qualquer outra coisa, façam tudo para a glória de Deus." },
  { "id": 239, "ref": "Jeremias 23:4", "texto": "Constituirei sobre elas pastores que as apascentarão; e não mais temerão, nem se aterrorizar, nem lhes faltará nenhuma, diz o Senhor." },
  { "id": 240, "ref": "Hebreus 13:16", "texto": "Não se esqueçam de fazer o bem e de repartir com os outros o que vocês têm, pois esses são os sacrifícios que agradam a Deus." },
  { "id": 241, "ref": "1 Pedro 5:6", "texto": "Portanto, humilhem-se sob a poderosa mão de Deus, para que ele os exalte no tempo devido." },
  { "id": 242, "ref": "Salmos 29:11", "texto": "O Senhor dá força ao seu povo; o Senhor abençoa o seu povo com paz." },
  { "id": 243, "ref": "Mateus 7:24", "texto": "Portanto, todo aquele que ouve estas minhas palavras e as põe em prática é como um homem sábio que construiu a sua casa sobre a rocha." },
  { "id": 244, "ref": "Salmos 145:4", "texto": "Uma geração louvará as tuas obras à outra; e anunciará os teus poderosos atos." },
  { "id": 245, "ref": "Isaías 66:2", "texto": "O meu olhar está voltado para os humildes e para os de espírito contrito, e para os que tremem diante de minha palavra." },
  { "id": 246, "ref": "João 15:13", "texto": "Ninguém tem maior amor do que este: dar a vida pelos seus amigos." },
  { "id": 247, "ref": "Colossenses 1:9-10", "texto": "Desde o dia em que ouvimos isso, não cessamos de orar por vocês. Pedimos que Deus os encha do conhecimento de sua vontade com toda a sabedoria e entendimento espiritual." },
  { "id": 248, "ref": "2 Coríntios 8:7", "texto": "Mas assim como vocês são excelentes em tudo: em fé, em palavras, em conhecimento, em toda diligência e no amor que vocês aprenderam conosco, vejam se também se sobressaem nessa graça de dar." },
  { "id": 249, "ref": "Provérbios 14:23", "texto": "Em todo trabalho haverá proveito, mas o vão discurso leva somente à pobreza." },
  { "id": 250, "ref": "Atos 11:23", "texto": "Ao chegar e ver a graça de Deus, alegrou-se e os encorajou a todos a permanecerem fiéis ao Senhor com coração sincero." },
  { "id": 251, "ref": "Salmos 86:11", "texto": "Ensina-me, Senhor, o teu caminho; andarei na tua verdade; une o meu coração para que tema o teu nome." },
  { "id": 252, "ref": "Lucas 1:17", "texto": "E ele irá adiante do Senhor com o espírito e poder de Elias, para converter os corações dos pais aos filhos e os desobedientes à sensatez dos justos, a fim de preparar para o Senhor um povo bem disposto." },
  { "id": 253, "ref": "1 Timóteo 6:12", "texto": "Combata o bom combate da fé; aposse-se da vida eterna, para a qual você foi chamado e da qual fez a boa confissão diante de muitas testemunhas." },
  { "id": 254, "ref": "Efésios 3:7", "texto": "Deste evangelho eu me tornei servo, segundo o dom da graça de Deus que me foi dado pela operação do seu poder." },
  { "id": 255, "ref": "Salmos 73:26", "texto": "A minha carne e o meu coração podem desfalecer, mas Deus é a força do meu coração e a minha herança para sempre." },
  { "id": 256, "ref": "João 6:38", "texto": "Pois desci do céu não para fazer a minha vontade, mas a vontade daquele que me enviou." },
  { "id": 257, "ref": "Romanos 12:3", "texto": "Pela graça que me foi dada, digo a cada um de vocês que não pense de si mesmo mais do que convém, mas pense com moderação, conforme a medida da fé que Deus concedeu a cada um." },
  { "id": 258, "ref": "Provérbios 29:18", "texto": "Sem visão profética, o povo perece; mas feliz é o que guarda a lei." },
  { "id": 259, "ref": "2 Timóteo 2:21", "texto": "Aquele que se apartar dessas coisas será um instrumento nobre, consagrado, útil ao seu Senhor e preparado para toda boa obra." },
  { "id": 260, "ref": "Mateus 10:19-20", "texto": "Quando os prenderam, não se preocupem com o que vão dizer ou como vão dizer, porque, naquela hora, lhes será dado o que devem dizer. Pois não serão vocês a falar, mas o Espírito do Pai falará por meio de vocês." },
  { "id": 261, "ref": "Salmos 37:30", "texto": "A boca do justo fala com sabedoria, e a sua língua expressa o que é justo." },
  { "id": 262, "ref": "1 Pedro 4:19", "texto": "Portanto, os que sofrem segundo a vontade de Deus, entreguem a sua alma ao fiel Criador e continuem fazendo o bem." },
  { "id": 263, "ref": "Atos 9:15", "texto": "Mas o Senhor disse a Ananias: Vai! Esse homem é um instrumento que escolhi para levar o meu nome às nações e aos seus reis e ao povo de Israel." },
  { "id": 264, "ref": "Salmos 119:90", "texto": "A tua fidelidade permanece para todas as gerações; tu estabeleceste a terra, e ela permanece firme." },
  { "id": 265, "ref": "Filipenses 4:9", "texto": "O que também aprendestes, e recebestes, e ouvistes, e vistes em mim, isso praticai; e o Deus de paz será convosco." },
  { "id": 266, "ref": "2 Coríntios 4:7", "texto": "Mas temos este tesouro em vasos de barro para que se veja que a suprema grandeza do poder é de Deus e não nossa." },
  { "id": 267, "ref": "Isaías 59:21", "texto": "O meu Espírito que está sobre ti, e as minhas palavras que pus na tua boca não se afastarão da tua boca, diz o Senhor." },
  { "id": 268, "ref": "Romanos 15:16", "texto": "Para ser ministro de Cristo Jesus entre os gentios, servindo como sacerdote no evangelho de Deus, a fim de que a oferta dos gentios seja agradável, santificada pelo Espírito Santo." },
  { "id": 269, "ref": "Lucas 22:32", "texto": "Mas eu orei por você, para que a sua fé não desfaleça. E você, quando se converter, fortaleça seus irmãos." },
  { "id": 270, "ref": "Salmos 111:10", "texto": "O temor do Senhor é o princípio da sabedoria; todos os que praticam os seus preceitos adquirem bom entendimento." },
  { "id": 271, "ref": "1 Coríntios 12:28", "texto": "E na igreja, Deus nomeou: em primeiro lugar apóstolos, em segundo lugar profetas, em terceiro lugar mestres; depois, os que fazem milagres, depois os que têm dons de curas, os que ajudam, os que administram." },
  { "id": 272, "ref": "Efésios 4:4-6", "texto": "Há um só corpo e um só Espírito, assim como a esperança para a qual vocês foram chamados é uma só; há um só Senhor, uma só fé, um só batismo; um só Deus e Pai de todos." },
  { "id": 273, "ref": "Tiago 5:14", "texto": "Algum de vocês está doente? Chame os presbíteros da igreja para orarem por ele e o ungirem com óleo em nome do Senhor." },
  { "id": 274, "ref": "Salmos 48:14", "texto": "Pois este Deus é o nosso Deus para sempre e eternamente; ele nos guiará para sempre." },
  { "id": 275, "ref": "2 Timóteo 4:5", "texto": "Quanto a você, mantenha a cabeça em todas as situações, suporte as dificuldades, faça a obra de um evangelista, cumpra plenamente o seu ministério." },
  { "id": 276, "ref": "João 3:30", "texto": "É necessário que ele cresça e que eu diminua." },
  { "id": 277, "ref": "Atos 2:17", "texto": "Nos últimos dias, diz Deus, derramarei o meu Espírito sobre toda a humanidade. Os filhos e as filhas de vocês profetizarão, os jovens terão visões, e os velhos terão sonhos." },
  { "id": 278, "ref": "Provérbios 12:24", "texto": "O trabalho diligente traz o domínio, mas a preguiça termina no trabalho forçado." },
  { "id": 279, "ref": "Romanos 8:31", "texto": "Que diremos então a estas coisas? Se Deus é por nós, quem será contra nós?" },
  { "id": 280, "ref": "1 Crônicas 29:5", "texto": "Quem pois se dispõe a consagrar-se hoje ao Senhor?" },
  { "id": 281, "ref": "Salmos 90:17", "texto": "Que o favor do Senhor nosso Deus repouse sobre nós; confirma a obra das nossas mãos; sim, confirma a obra das nossas mãos." },
  { "id": 282, "ref": "Mateus 6:33", "texto": "Busquem, pois, em primeiro lugar o Reino de Deus e a sua justiça, e todas essas coisas lhes serão acrescentadas." },
  { "id": 283, "ref": "Isaías 30:21", "texto": "Quando vocês se desviarem para a direita ou para a esquerda, os seus ouvidos ouvirão uma voz atrás de vocês, dizendo: Este é o caminho, andem por ele." },
  { "id": 284, "ref": "Hebreus 12:2", "texto": "Fixemos o olhar em Jesus, o autor e aperfeiçoador da fé, o qual pelo gozo que lhe estava proposto suportou a cruz, não fazendo caso da vergonha, e está assentado à direita do trono de Deus." },
  { "id": 285, "ref": "1 Tessalonicenses 4:11", "texto": "E que tenhais por ambição viver em paz, tratar dos vossos próprios negócios e trabalhar com as vossas mãos, como vos ordenamos." },
  { "id": 286, "ref": "Atos 6:8", "texto": "Estêvão, cheio de graça e de poder, realizava grandes maravilhas e sinais entre o povo." },
  { "id": 287, "ref": "Colossenses 3:17", "texto": "E tudo o que fizerem, seja em palavras ou em ações, façam em nome do Senhor Jesus, dando graças a Deus Pai por meio dele." },
  { "id": 288, "ref": "Salmos 105:1", "texto": "Louvai ao Senhor, invocai o seu nome; fazei conhecidas entre os povos as suas obras." },
  { "id": 289, "ref": "2 Pedro 1:3", "texto": "O seu divino poder nos deu tudo de que necessitamos para a vida e para a piedade, por meio do conhecimento daquele que nos chamou para a sua própria glória e virtude." },
  { "id": 290, "ref": "Lucas 6:38", "texto": "Deem, e lhes será dado: uma boa medida, calcada, sacudida e transbordando será colocada no colo de vocês. Pois com a medida que usarem, será medido para vocês." },
  { "id": 291, "ref": "Salmos 145:10-11", "texto": "Todas as tuas obras te louvam, Senhor, e os teus santos te bendizem. Falam da glória do teu reino e proclamam o teu poder." },
  { "id": 292, "ref": "João 14:12", "texto": "Digo-lhes a verdade: Aquele que crê em mim fará também as obras que tenho feito, e fará coisas maiores do que estas, porque eu estou indo para o Pai." },
  { "id": 293, "ref": "Romanos 12:2", "texto": "Não se amoldem ao padrão deste mundo, mas transformem-se pela renovação da sua mente, para que sejam capazes de experimentar e comprovar a boa, agradável e perfeita vontade de Deus." },
  { "id": 294, "ref": "Provérbios 16:9", "texto": "O coração do homem planeja o seu caminho, mas é o Senhor quem lhe dirige os passos." },
  { "id": 295, "ref": "Efésios 6:18", "texto": "Orando em todo o tempo com toda oração e súplica no Espírito, e para isso vigiando com toda perseverança e súplica por todos os santos." },
  { "id": 296, "ref": "1 João 3:18", "texto": "Meus filhos, não amemos de palavras, nem de língua, mas em ações e em verdade." },
  { "id": 297, "ref": "Salmos 50:15", "texto": "Invoca-me no dia da angústia; eu te livrarei, e tu me glorificarás." },
  { "id": 298, "ref": "Deuteronômio 6:5", "texto": "Ame o Senhor, o seu Deus, de todo o seu coração, de toda a sua alma e de todas as suas forças." },
  { "id": 299, "ref": "Atos 2:47", "texto": "E o Senhor acrescentava-lhes diariamente os que iam sendo salvos." },
  { "id": 300, "ref": "Apocalipse 3:8", "texto": "Conheço os seus feitos. Eis que pus à sua frente uma porta aberta, que ninguém pode fechar. Pois, com pouca força, guardaste a minha palavra e não negaste o meu nome." },
  { "id": 301, "ref": "Salmos 4:3", "texto": "Saibam que o Senhor separa para si o piedoso; o Senhor ouvirá quando eu o invocar." },
  { "id": 302, "ref": "Isaías 43:1", "texto": "Mas agora, assim diz o Senhor, aquele que te criou, ó Jacó, aquele que te formou, ó Israel: Não temas, porque eu te remi; chamei-te pelo teu nome; tu és meu." },
  { "id": 303, "ref": "2 Coríntios 6:1", "texto": "Como colaboradores que somos com Deus, exortamos também a que não recebais em vão a graça de Deus." },
  { "id": 304, "ref": "Lucas 10:17", "texto": "Os setenta e dois voltaram cheios de alegria e disseram: Senhor, até os demônios se submetem a nós em teu nome." },
  { "id": 305, "ref": "1 Timóteo 3:10", "texto": "Estes devem ser primeiro testados; depois, se não houver nada contra eles, que sirvam como diáconos." },
  { "id": 306, "ref": "Salmos 145:18", "texto": "O Senhor está perto de todos os que o invocam, de todos os que o invocam de verdade." },
  { "id": 307, "ref": "João 16:33", "texto": "Eu lhes disse essas coisas para que em mim vocês tenham paz. Neste mundo vocês terão aflições; contudo, tenham ânimo! Eu venci o mundo." },
  { "id": 308, "ref": "Romanos 14:19", "texto": "Portanto, procuremos o que contribui para a paz e para a edificação mútua." },
  { "id": 309, "ref": "Provérbios 3:27", "texto": "Não sonegues o bem a quem é devido quando estiver em teu poder fazê-lo." },
  { "id": 310, "ref": "Salmos 62:8", "texto": "Confiem nele em todo o tempo, ó povo; derramai o vosso coração diante dele; Deus é o nosso refúgio." },
  { "id": 311, "ref": "Efésios 3:16-17", "texto": "Peço a Deus que, segundo as riquezas da sua glória, ele os fortaleça com poder por meio do seu Espírito no homem interior, para que Cristo habite em seus corações pela fé." },
  { "id": 312, "ref": "2 Timóteo 2:24", "texto": "O servo do Senhor não deve ser brigão, mas manso para com todos, hábil para ensinar, sofredor." },
  { "id": 313, "ref": "Atos 3:6", "texto": "Mas Pedro disse: Prata e ouro não tenho, mas o que tenho isso te dou: Em nome de Jesus Cristo de Nazaré, levanta-te e anda." },
  { "id": 314, "ref": "Mateus 11:28-29", "texto": "Venham a mim, todos vocês que estão cansados e sobrecarregados, e eu darei descanso a vocês. Tomem sobre vocês o meu jugo e aprendam de mim, pois sou manso e humilde de coração." },
  { "id": 315, "ref": "Salmos 119:165", "texto": "Grande paz têm os que amam a tua lei; coisa alguma os faz tropeçar." },
  { "id": 316, "ref": "1 Coríntios 11:1", "texto": "Sede meus imitadores, como também eu o sou de Cristo." },
  { "id": 317, "ref": "Jeremias 33:3", "texto": "Clama a mim, e eu te responderei, e anunciar-te-ei coisas grandes e ocultas, que não sabes." },
  { "id": 318, "ref": "Filipenses 4:7", "texto": "E a paz de Deus, que excede todo o entendimento, guardará os seus corações e as suas mentes em Cristo Jesus." },
  { "id": 319, "ref": "Lucas 24:49", "texto": "Vou enviar sobre vocês o que meu Pai prometeu; mas fiquem na cidade até que sejam revestidos do poder do alto." },
  { "id": 320, "ref": "Salmos 21:13", "texto": "Sê exaltado, ó Senhor, na tua força; cantaremos e louvaremos o teu poder." },
  { "id": 321, "ref": "Atos 10:38", "texto": "Como Deus ungiu com o Espírito Santo e com poder a Jesus de Nazaré, que andou por toda parte fazendo o bem e curando todos os oprimidos pelo diabo, porque Deus estava com ele." },
  { "id": 322, "ref": "Colossenses 4:2", "texto": "Dediquem-se à oração; estejam vigilantes nela e sejam agradecidos." },
  { "id": 323, "ref": "2 Coríntios 13:11", "texto": "Finalmente, irmãos, regozijai-vos, tornai-vos perfeitos, sede confortados, sede de um mesmo parecer, vivei em paz; e o Deus de amor e de paz será convosco." },
  { "id": 324, "ref": "Provérbios 19:21", "texto": "Muitos planos há no coração do homem, mas o que prevalece é o propósito do Senhor." },
  { "id": 325, "ref": "Salmos 37:28", "texto": "Porque o Senhor ama a justiça e não abandona os seus santos; eles são preservados para sempre." },
  { "id": 326, "ref": "1 Tessalonicenses 5:17", "texto": "Orai sem cessar." },
  { "id": 327, "ref": "Isaías 26:3", "texto": "Tu conservarás em paz aquele cuja mente está firmada em ti, porque ele confia em ti." },
  { "id": 328, "ref": "João 15:7", "texto": "Se vocês permanecerem em mim e as minhas palavras permanecerem em vocês, pedirão o que quiserem, e lhes será concedido." },
  { "id": 329, "ref": "Romanos 16:19", "texto": "Pois o que se diz da obediência de vocês chegou a todos; alegro-me, pois, a respeito de vocês, mas quero que sejam sábios para o bem e inculpáveis para o mal." },
  { "id": 330, "ref": "Hebreus 12:14", "texto": "Esforcem-se para viver em paz com todos e para ser santos; sem a santidade ninguém verá o Senhor." },
  { "id": 331, "ref": "Salmos 130:7", "texto": "Israel, ponha a sua esperança no Senhor, porque no Senhor há misericórdia inesgotável e nele há plena redenção." },
  { "id": 332, "ref": "2 Crônicas 16:9", "texto": "Porque os olhos do Senhor perscrutam toda a terra, para mostrar a sua força a favor dos que têm o coração íntegro para com ele." },
  { "id": 333, "ref": "Mateus 19:26", "texto": "Jesus olhou para eles e disse: Para os homens isso é impossível, mas para Deus tudo é possível." },
  { "id": 334, "ref": "Efésios 5:1-2", "texto": "Portanto, sejam imitadores de Deus, como filhos amados, e vivam em amor, assim como Cristo nos amou e se entregou por nós." },
  { "id": 335, "ref": "Salmos 107:2", "texto": "Assim digam os remidos do Senhor, os que ele resgatou da mão do adversário." },
  { "id": 336, "ref": "Provérbios 21:5", "texto": "Os planos do diligente certamente trazem abundância, mas o que age precipitadamente certamente terá escassez." },
  { "id": 337, "ref": "Atos 4:20", "texto": "Não podemos deixar de falar das coisas que vimos e ouvimos." },
  { "id": 338, "ref": "1 Coríntios 13:13", "texto": "Agora, pois, permanecem a fé, a esperança e o amor, estes três; porém o maior destes é o amor." },
  { "id": 339, "ref": "Salmos 119:59-60", "texto": "Considerei os meus caminhos e voltei os meus passos aos teus testemunhos. Apressei-me e não me detive em guardar os teus mandamentos." },
  { "id": 340, "ref": "João 13:35", "texto": "Por isso todos saberão que vocês são meus discípulos, se vocês se amarem uns aos outros." },
  { "id": 341, "ref": "2 Coríntios 9:6", "texto": "Lembrem-se disto: aquele que semeia pouco colherá pouco; e aquele que semeia muito colherá muito." },
  { "id": 342, "ref": "Romanos 5:5", "texto": "E a esperança não nos envergonha, porque o amor de Deus foi derramado em nossos corações pelo Espírito Santo que nos foi dado." },
  { "id": 343, "ref": "Tito 1:9", "texto": "Deve apegar-se firmemente à mensagem fiel, que está de acordo com o ensinamento, para que possa exortar os outros com a sã doutrina e refutar os que se opõem a ela." },
  { "id": 344, "ref": "Salmos 119:130", "texto": "A explicação das tuas palavras ilumina e dá entendimento aos simples." },
  { "id": 345, "ref": "Mateus 5:9", "texto": "Bem-aventurados os pacificadores, porque serão chamados filhos de Deus." },
  { "id": 346, "ref": "Isaías 54:17", "texto": "Nenhuma arma forjada contra você prosperará, e você condenará toda língua que se levantar contra você em juízo. Esta é a herança dos servos do Senhor." },
  { "id": 347, "ref": "1 Coríntios 2:4-5", "texto": "Minha mensagem e minha pregação não se apoiaram em palavras persuasivas de sabedoria, mas em demonstração do poder do Espírito, para que a fé de vocês não se baseasse na sabedoria humana, mas no poder de Deus." },
  { "id": 348, "ref": "Salmos 37:11", "texto": "Mas os humildes herdarão a terra e desfrutarão de uma abundante prosperidade." },
  { "id": 349, "ref": "Atos 2:38", "texto": "Arrependam-se, e cada um de vocês seja batizado em nome de Jesus Cristo para o perdão dos seus pecados, e vocês receberão o dom do Espírito Santo." },
  { "id": 350, "ref": "Filipenses 3:17", "texto": "Juntos, sigam o meu exemplo, irmãos, e observem atentamente os que vivem de acordo com o modelo que lhes demos." },
  { "id": 351, "ref": "Salmos 119:18", "texto": "Abre os meus olhos para que eu contemple as coisas maravilhosas da tua lei." },
  { "id": 352, "ref": "Provérbios 25:11", "texto": "Como maçãs de ouro em ornamentos de prata, assim é a palavra dita em tempo oportuno." },
  { "id": 353, "ref": "João 14:26", "texto": "Mas o Consolador, o Espírito Santo, que o Pai enviará em meu nome, ensinará todas as coisas a vocês e fará com que se lembrem de tudo o que eu disse a vocês." },
  { "id": 354, "ref": "Romanos 8:26", "texto": "Da mesma forma, o Espírito nos ajuda em nossa fraqueza, pois não sabemos como orar, mas o próprio Espírito intercede por nós com gemidos inexprimíveis." },
  { "id": 355, "ref": "2 Crônicas 20:15", "texto": "A batalha não é de vocês, mas de Deus." },
  { "id": 356, "ref": "Salmos 34:18", "texto": "O Senhor está perto dos que têm o coração partido e salva os que estão com o espírito abatido." },
  { "id": 357, "ref": "Mateus 10:32", "texto": "Todo aquele, pois, que me confessar diante dos homens, eu também o confessarei diante do meu Pai que está nos céus." },
  { "id": 358, "ref": "Efésios 4:1", "texto": "Portanto, eu, prisioneiro pelo Senhor, exorto-lhes a que vivam de maneira digna do chamado que vocês receberam." },
  { "id": 359, "ref": "1 Pedro 5:4", "texto": "E quando o Supremo Pastor aparecer, vocês receberão a coroa de glória que nunca se murchará." },
  { "id": 360, "ref": "Salmos 57:2", "texto": "Clamou ao Deus Altíssimo, ao Deus que cumpre o seu propósito em meu favor." }
];

class VersiculoService {
  static Future<Map<String, String>> getVersiculoDoDia() async {
    final dataBase = DateTime(2026, 1, 1);
    final hoje = DateTime.now();
    
    final dataBaseZerada = DateTime(dataBase.year, dataBase.month, dataBase.day);
    final hojeZerado = DateTime(hoje.year, hoje.month, hoje.day);
    
    final diasDecorridos = hojeZerado.difference(dataBaseZerada).inDays;
    
    final idx = diasDecorridos % _versiculosLocal.length;
    final local = _versiculosLocal[idx];
    
    return {
      'texto': local['texto'].toString(),
      'ref': local['ref'].toString(),
    };
  }
}
